/**
 * Stage 5d - Firstpos Calculation.
 *
 * OWNER: Person 1.
 * CONTRACT: computes the set of positions of the first symbols of strings
 * generated by the subexpression rooted at `node`.
 *
 * Rules:
 *  - symbol with position i: { i }
 *  - union(A, B): firstpos(A) ∪ firstpos(B)
 *  - concat(A, B): nullable(A) ? (firstpos(A) ∪ firstpos(B)) : firstpos(A)
 *  - star(A): firstpos(A)
 *
 * Invariant: all returned position sets are sorted in ascending order with no duplicates.
 */

import { calculateNullable } from './nullable';
import type { SyntaxNode } from './types';

/**
 * Returns the sorted union of two position arrays with duplicates removed.
 */
export function unionPositions(a: number[], b: number[]): number[] {
  const set = new Set<number>([...a, ...b]);
  return [...set].sort((x, y) => x - y);
}

/**
 * Computes and sets `firstpos` for `node` and all of its descendants.
 *
 * @param node The syntax tree node to analyze.
 * @returns Sorted, deduplicated position array.
 */
export function calculateFirstpos(node: SyntaxNode): number[] {
  switch (node.type) {
    case 'symbol':
      node.firstpos = node.position !== undefined ? [node.position] : [];
      break;

    case 'union': {
      const leftFirst = node.left ? calculateFirstpos(node.left) : [];
      const rightFirst = node.right ? calculateFirstpos(node.right) : [];
      node.firstpos = unionPositions(leftFirst, rightFirst);
      break;
    }

    case 'concat': {
      const leftFirst = node.left ? calculateFirstpos(node.left) : [];
      const rightFirst = node.right ? calculateFirstpos(node.right) : [];
      const leftNullable = node.left ? (node.left.nullable ?? calculateNullable(node.left)) : false;

      node.firstpos = leftNullable ? unionPositions(leftFirst, rightFirst) : [...leftFirst];
      break;
    }

    case 'star': {
      const childFirst = node.left ? calculateFirstpos(node.left) : [];
      node.firstpos = [...childFirst];
      break;
    }
  }

  return node.firstpos;
}
